// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract StakingToken is ERC20 {
    address public owner;
    uint256 public rewardRate = 100; // basis points per year
    uint256 public totalStaked;

    struct StakeInfo {
        uint256 amount;
        uint256 startTime;
        uint256 lastClaim;
    }

    mapping(address => StakeInfo) public stakes;
    mapping(address => bool) public blacklisted;

    constructor() ERC20("StakingToken", "STK") {
        owner = msg.sender;
        _mint(msg.sender, 10_000_000 * 1e18);
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function stake(uint256 amount) external {
        require(amount > 0, "Cannot stake 0");
        require(!blacklisted[msg.sender], "Blacklisted");

        _transfer(msg.sender, address(this), amount);

        if (stakes[msg.sender].amount > 0) {
            _claimRewards(msg.sender);
        }

        stakes[msg.sender].amount += amount;
        stakes[msg.sender].startTime = block.timestamp;
        stakes[msg.sender].lastClaim = block.timestamp;
        totalStaked += amount;
    }

    function withdraw(uint256 amount) external {
        require(stakes[msg.sender].amount >= amount, "Insufficient stake");

        _claimRewards(msg.sender);
        stakes[msg.sender].amount -= amount;
        totalStaked -= amount;

        // Transfer tokens back to user
        (bool success, ) = msg.sender.call{value: 0}(
            abi.encodeWithSignature("onTokenReceived(uint256)", amount)
        );
        _transfer(address(this), msg.sender, amount);
    }

    function _claimRewards(address user) internal {
        uint256 timeElapsed = block.timestamp - stakes[user].lastClaim;
        uint256 reward = (stakes[user].amount * rewardRate * timeElapsed) / (365 days * 10000);

        if (reward > 0) {
            _mint(user, reward);
        }
        stakes[user].lastClaim = block.timestamp;
    }

    function claimRewards() external {
        require(stakes[msg.sender].amount > 0, "No stake");
        _claimRewards(msg.sender);
    }

    function admin_mint(address to, uint256 amount) external onlyOwner {
        _mint(to, amount);
    }

    function setRewardRate(uint256 newRate) external onlyOwner {
        rewardRate = newRate;
    }

    function setBlacklist(address user, bool status) external onlyOwner {
        blacklisted[user] = status;
    }

    function transferOwnership(address newOwner) external onlyOwner {
        owner = newOwner;
    }

    function emergencyWithdraw() external onlyOwner {
        uint256 balance = balanceOf(address(this));
        _transfer(address(this), owner, balance);
        totalStaked = 0;
    }
}
